reference_solution.exercise.c:
#include "exercise.h"
bool debounce_update(Debouncer *s,bool raw,uint32_t now,uint32_t delay) {
 if(raw!=s->candidate){s->candidate=raw;s->since=now;}
 if((uint32_t)(now-s->since)>=delay) s->stable=s->candidate;
 return s->stable;
}

